// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.voice.audio/** * NOUS — Voice Activity Detector (VAD). * * Determines whether an audio chunk contains human speech or just background * noise / silence. Used by: * *   - **WakeWordDetector** — skip non-voice audio (60% battery savings) *   - **BargeInDetector** — detect when user starts speaking during TTS *   - **ConversationEngine** — silence-based end-of-speech detection *   - **AudioCapturePipeline** — gate downstream processing on voice presence * * ## Algorithm (multi-band energy-based) * * NOUS uses a lightweight multi-band energy VAD inspired by WebRTC's `webrtc_vad` * but implemented in pure Kotlin (no native dependency). The algorithm: * *   1. Split the chunk into 6 sub-bands (0-1kHz, 1-2kHz, ..., 5-6kHz) *   2. Compute per-band RMS energy *   3. Compare each band's energy against the noise floor estimate *   4. If 3+ bands exceed their noise floor by [bandMarginDb], declare VOICE * * This is more accurate than a single RMS threshold because: *   - Background noise (fans, A/C) tends to be low-frequency *   - Speech has energy distributed across multiple bands *   - Sirens / alarms (which can fool single-band VAD) typically don't have *     the right spectral shape for speech * * ## Aggressiveness * * Three levels matching WebRTC's API: *   - **QUALITY** (0) — most permissive, lowest false-negative rate *   - **BALANCED** (1) — default, good for most environments *   - **AGGRESSIVE** (2) — strictest, may miss quiet speech * * ## Noise Floor Adaptation * * The VAD maintains an exponential moving average (EMA) of background noise * energy per band. When the VAD declares NO_VOICE, the noise floor is updated * to track slowly-changing background noise (HVAC, traffic). * * When VOICE is detected, the noise floor is NOT updated (to avoid the VAD * locking onto speech as the new "noise floor" and going deaf). * * ## Performance * *   - Per chunk: ~0.05 ms (320 samples, 6 bands, integer math) *   - Allocations: 0 (reuses internal buffers) *   - Suitable for real-time use on the audio capture thread * * @see <a href="docs/strategy/module-5-strategy-v2.md">§5 Audio Capture Pipeline</a> */class VoiceActivityDetector(    /** Aggressiveness level. Higher = stricter (more likely to declare NO_VOICE). */    private val aggressiveness: VadAggressiveness = VadAggressiveness.BALANCED,    /** Initial noise floor estimate in dBFS (decibels relative to full scale). */    initialNoiseFloorDb: Float = DEFAULT_NOISE_FLOOR_DB,    /** Smoothing factor for noise floor EMA (0.0 = no update, 1.0 = instant). */    private val noiseFloorSmoothing: Float = DEFAULT_NOISE_SMOOTHING,) {    /** Per-band noise floor estimate (dBFS). */    private val noiseFloorDb: FloatArray = FloatArray(NUM_BANDS) { initialNoiseFloorDb }    /** Number of consecutive NO_VOICE chunks seen (for state tracking). */    private var consecutiveSilentChunks: Int = 0    /** Number of consecutive VOICE chunks seen (for state tracking). */    private var consecutiveVoiceChunks: Int = 0    /**     * Detect voice activity in an audio chunk.     *     * @param chunk the audio chunk to analyze (typically 20 ms, 16 kHz mono)     * @return VAD result with voice/silence decision and per-band energies     */    fun detect(chunk: AudioChunk): VadResult {        require(chunk.format.sampleRateHz == 16_000) {            "VAD requires 16 kHz audio, got ${chunk.format.sampleRateHz}"        }        val bandEnergiesDb = computeBandEnergiesDb(chunk.samples)        // Count how many bands exceed their noise floor by the required margin        val marginDb = aggressiveness.marginDb        var voiceBands = 0        for (i in 0 until NUM_BANDS) {            if (bandEnergiesDb[i] > noiseFloorDb[i] + marginDb) {                voiceBands++            }        }        // Decision: voice if enough bands exceed noise floor        val isVoice = voiceBands >= aggressiveness.minVoiceBands        // Update noise floor (only on silence to avoid locking onto speech)        if (!isVoice) {            for (i in 0 until NUM_BANDS) {                noiseFloorDb[i] = (noiseFloorDb[i] * (1f - noiseFloorSmoothing)) +                    (bandEnergiesDb[i] * noiseFloorSmoothing)            }            consecutiveSilentChunks++            consecutiveVoiceChunks = 0        } else {            consecutiveSilentChunks = 0            consecutiveVoiceChunks++        }        return VadResult(            isVoice = isVoice,            bandEnergiesDb = bandEnergiesDb,            voiceBandCount = voiceBands,            consecutiveVoiceChunks = consecutiveVoiceChunks,            consecutiveSilentChunks = consecutiveSilentChunks,            noiseFloorDb = noiseFloorDb.copyOf(),        )    }    /**     * Quick voice-presence check (no detailed result).     *     * Use this in hot paths where only the boolean is needed (e.g., wake word     * pre-filter). Avoids allocating the [VadResult] object.     */    fun hasVoice(chunk: AudioChunk): Boolean = detect(chunk).isVoice    /** Reset VAD state (noise floor + counters). Call on session start. */    fun reset() {        for (i in 0 until NUM_BANDS) noiseFloorDb[i] = DEFAULT_NOISE_FLOOR_DB        consecutiveSilentChunks = 0        consecutiveVoiceChunks = 0    }    /** Current noise floor estimate (snapshot). */    fun getNoiseFloorDb(): FloatArray = noiseFloorDb.copyOf()    /**     * Compute per-band RMS energy in dBFS for the given samples.     *     * Uses a direct DFT (Discrete Fourier Transform) to compute the magnitude     * spectrum, then groups bins into [NUM_BANDS] frequency bands of equal     * width. For 16 kHz audio with N=320 samples, the DFT produces 160 unique     * bins (Nyquist), each 50 Hz wide. With 6 bands of ~26 bins each, each     * band covers ~1.3 kHz — wide enough to capture speech harmonics.     *     * ## Why DFT, not time-domain splitting?     *     * A naive approach splits samples into N groups and computes RMS per group.     * This DOES NOT correspond to frequency bands — a 500 Hz sine wave would     * have the same RMS in every group, making single-frequency detection     * impossible. The DFT correctly localizes energy to specific frequency     * bands, which is essential for distinguishing voiced speech (multi-band)     * from pure tones (single-band).     *     * ## Normalization     *     * For real-valued input, we use the one-sided spectrum (bins 0 to N/2).     * Energy from negative frequencies is folded into positive frequencies     * by doubling (except DC and Nyquist bins). Per Parseval's theorem:     *     *   time-domain RMS² = (1/N²) × Σ |X[k]|² × 2  (for 1 ≤ k < N/2)     *     * We compute: rms = sqrt(2 × Σ|X[k]|²) / N     *     * ## Performance     *     * Direct DFT is O(N²) — for N=320, that's ~50k multiply-adds per chunk,     * taking ~0.1 ms on a modern arm64 CPU. At 50 chunks/sec, total CPU is     * ~5 ms/sec (negligible). For higher performance, a radix-2 FFT could     * reduce to O(N log N), but the complexity isn't justified at this scale.     *     * Cosine/sine tables are precomputed lazily on first use and cached for     * the lifetime of the VAD instance, avoiding repeated trig calls.     */    private fun computeBandEnergiesDb(samples: ShortArray): FloatArray {        val n = samples.size        val halfN = n / 2        // Precompute twiddle tables (cos/sin) for this N if not already cached        ensureTwiddleTables(n)        // Compute DFT magnitudes (one-sided spectrum)        val mags = DoubleArray(halfN)        val normalized = FloatArray(n)        for (i in 0 until n) {            normalized[i] = samples[i].toFloat() / Short.MAX_VALUE        }        for (k in 0 until halfN) {            var real = 0.0            var imag = 0.0            for (i in 0 until n) {                val idx = (k * i) % n                real += normalized[i] * cosTable[idx]                imag -= normalized[i] * sinTable[idx]            }            mags[k] = kotlin.math.sqrt(real * real + imag * imag)        }        // Group bins into bands (equal-width)        val binsPerBand = halfN / NUM_BANDS        val result = FloatArray(NUM_BANDS)        for (band in 0 until NUM_BANDS) {            val start = band * binsPerBand            val end = if (band == NUM_BANDS - 1) halfN else start + binsPerBand            var sumMagSq = 0.0            for (k in start until end) {                // Double the energy for non-DC, non-Nyquist bins (one-sided spectrum)                val weight = if (k == 0 || k == halfN) 1.0 else 2.0                sumMagSq += weight * mags[k] * mags[k]            }            // RMS = sqrt(energy) / N, where energy = sum of weighted |X[k]|²            val rms = if (end > start) kotlin.math.sqrt(sumMagSq) / n else 0.0            // dBFS: 20 * log10(rms). For silence (rms=0), return very low value.            result[band] = if (rms > 1e-10) (20f * kotlin.math.log10(rms).toFloat()) else -120f        }        return result    }    /** Precomputed cosine table for DFT (lazily initialized). */    private var cosTable: FloatArray = FloatArray(0)    /** Precomputed sine table for DFT (lazily initialized). */    private var sinTable: FloatArray = FloatArray(0)    /** N for which the current twiddle tables were computed. */    private var twiddleN: Int = 0    /** Initialize cos/sin tables for the given DFT size N. */    private fun ensureTwiddleTables(n: Int) {        if (twiddleN == n && cosTable.size == n) return        twiddleN = n        cosTable = FloatArray(n)        sinTable = FloatArray(n)        for (i in 0 until n) {            val angle = -2.0 * Math.PI * i / n            cosTable[i] = kotlin.math.cos(angle).toFloat()            sinTable[i] = kotlin.math.sin(angle).toFloat()        }    }    companion object {        /** Number of frequency bands (6 bands × 1 kHz each = 0-6 kHz). */        const val NUM_BANDS = 6        /** Default noise floor: -50 dBFS (typical for quiet room). */        const val DEFAULT_NOISE_FLOOR_DB = -50f        /** Default EMA smoothing factor for noise floor. */        const val DEFAULT_NOISE_SMOOTHING = 0.05f    }}/** * VAD aggressiveness level. * * Higher aggressiveness means the VAD requires more bands to be above the * noise floor (and a larger margin), reducing false positives at the cost of * potentially missing quiet speech. */enum class VadAggressiveness(    /** Minimum bands above noise floor + margin to declare VOICE. */    val minVoiceBands: Int,    /** Required margin above noise floor in dB. */    val marginDb: Float,) {    /** Quality mode — most permissive (good for quiet talkers). */    QUALITY(minVoiceBands = 2, marginDb = 3f),    /** Balanced mode — default, works well for most environments. */    BALANCED(minVoiceBands = 3, marginDb = 6f),    /** Aggressive mode — strict, rejects more borderline audio. */    AGGRESSIVE(minVoiceBands = 4, marginDb = 10f),    ;    companion object {        /** WebRTC-style 0-2 integer → enum. */        fun fromInt(level: Int): VadAggressiveness = when (level) {            0 -> QUALITY            1 -> BALANCED            2 -> AGGRESSIVE            else -> throw IllegalArgumentException("VAD aggressiveness must be 0-2, got $level")        }    }}/** * VAD result for a single chunk. * * @see VoiceActivityDetector.detect */data class VadResult(    /** Whether this chunk is classified as containing voice. */    val isVoice: Boolean,    /** Per-band RMS energy in dBFS (size = [VoiceActivityDetector.NUM_BANDS]). */    val bandEnergiesDb: FloatArray,    /** Number of bands that exceeded the noise floor + margin. */    val voiceBandCount: Int,    /** Consecutive VOICE chunks up to and including this one. */    val consecutiveVoiceChunks: Int,    /** Consecutive NO_VOICE chunks up to and including this one. */    val consecutiveSilentChunks: Int,    /** Snapshot of the noise floor at decision time (size = NUM_BANDS). */    val noiseFloorDb: FloatArray,) {    /** Whether this chunk marks the start of speech (first voice chunk after silence). */    val isVoiceOnset: Boolean get() = isVoice && consecutiveVoiceChunks == 1    /** Whether this chunk marks the start of silence (first silent chunk after voice). */    val isSilenceOnset: Boolean get() = !isVoice && consecutiveSilentChunks == 1    override fun equals(other: Any?): Boolean {        if (this === other) return true        if (javaClass != other?.javaClass) return false        val o = other as? VadResult ?: return false        if (isVoice != o.isVoice) return false        if (!bandEnergiesDb.contentEquals(o.bandEnergiesDb)) return false        if (voiceBandCount != o.voiceBandCount) return false        if (consecutiveVoiceChunks != o.consecutiveVoiceChunks) return false        if (consecutiveSilentChunks != o.consecutiveSilentChunks) return false        if (!noiseFloorDb.contentEquals(o.noiseFloorDb)) return false        return true    }    override fun hashCode(): Int {        var result = isVoice.hashCode()        result = 31 * result + bandEnergiesDb.contentHashCode()        result = 31 * result + voiceBandCount        result = 31 * result + consecutiveVoiceChunks        result = 31 * result + consecutiveSilentChunks        result = 31 * result + noiseFloorDb.contentHashCode()        return result    }}